const [route, Collection, RouteParameters, Stop] = await $arcgis.import([  "@arcgis/core/rest/route.js",  "@arcgis/core/core/Collection.js",  "@arcgis/core/rest/support/RouteParameters.js",  "@arcgis/core/rest/support/Stop.js"]);
// point the URL to a valid routing serviceconst routeUrl =  "https://route-api.arcgis.com/arcgis/rest/services/World/Route/NAServer/Route_World";
// create a Collection of new Stopsconst stops = new Collection([  new Stop({    geometry: { x: -117.59275, y: 34.06200 },    name: "Ontario Airport"  }),  new Stop({    geometry: { x: -117.19570, y: 34.05609 },    name: "Esri Campus"  })]);
// setup the RouteParameters with API key and Stopsconst routeParams = new RouteParameters({  // An authorization string used to access the routing service  apiKey: "YOUR_API_KEY",  stops});
// solve the route with the RouteParametersfunction solveRoute() {  route.solve(routeUrl, routeParams).then(showRouteInfo);}
// do something useful with the results// like display them to the consolefunction showRouteInfo(routeSolveResult) {  console.log("Show all results: ", routeSolveResult);  console.log("Show the route information: ", routeSolveResult.routeResults[0].route);}
solveRoute();
```

