      // Setup the route parameters      const routeParams = new RouteParameters({        // An authorization string used to access the routing service        apiKey: "YOUR_ACCESS_TOKEN",        stops: new FeatureSet(),        outSpatialReference: {          // autocasts as new SpatialReference()          wkid: 3857,        },      });
