Geoapify | How to Plan a Bicycle Route with Bike Type, Surface, and Elevation | Geoapify > Summarize meters by surface

Add up distance for each value of a step field across all legs. The same function works for surface and road_class . It expects a JSON response ( format=json ) requested with details=route_details .

```
function sumStepDistance(routingResponse, field) {
  const totals = {};

for (const leg of routingResponse.results[0].legs) {
    for (const step of leg.steps) {
      // The arrival step has zero distance and no road properties.
      if (!step.distance) continue;

const value = step[field] ?? "unknown";
      totals[value] = (totals[value] ?? 0) + step.distance;
    }
  }

return totals;
}

function toShares(totals) {
  const total = Object.values(totals).reduce((sum, meters) => sum + meters, 0);

return Object.entries(totals)
    .sort(([, a], [, b]) => b - a)
    .map(([value, meters]) => ({
      value,
      meters,
      share: Math.round(meters / total * 1000) / 10 // percent, one decimal
    }));
}

const surfaces = toShares(sumStepDistance(routingResponse, "surface"));
const roadClasses = toShares(sumStepDistance(routingResponse, "road_class"));
```

